public interface NotificationSender {
    boolean send(String recipient, String message);
    String getChannelName();
}

// 1. Abstract Base Sender implementing Template Method pattern
abstract class BaseSender implements NotificationSender {
    private int deliveryCount = 0;

    // Template method: final to enforce invariant logging & validation
    @Override
    public final boolean send(String recipient, String message) {
        if (recipient == null || recipient.trim().isEmpty()) {
            System.err.printf("[%s] Error: Recipient cannot be empty.%n", getChannelName());
            return false;
        }
        if (message == null || message.trim().isEmpty()) {
            System.err.printf("[%s] Error: Message body cannot be empty.%n", getChannelName());
            return false;
        }

        // Delegate channel-specific delivery to subclass
        boolean success = deliver(recipient.trim(), message.trim());
        if (success) {
            deliveryCount++;
        }
        return success;
    }

    // Primitive step to be implemented by concrete channels
    protected abstract boolean deliver(String recipient, String message);

    public int getDeliveryCount() { return deliveryCount; }
}

// 2. Email Sender Implementation
class EmailSender extends BaseSender {
    @Override
    public String getChannelName() { return "EMAIL"; }

    @Override
    protected boolean deliver(String recipient, String message) {
        if (!recipient.contains("@") || !recipient.contains(".")) {
            System.err.printf("[EMAIL] Delivery failed: Invalid email format '%s'.%n", recipient);
            return false;
        }
        System.out.printf("[EMAIL] -> %s%n  Subject: [ALERT] System Notification%n  Body: %s%n  Status: DELIVERED%n", 
            recipient, message);
        return true;
    }
}

// 3. SMS Sender Implementation (160-char truncation)
class SmsSender extends BaseSender {
    @Override
    public String getChannelName() { return "SMS"; }

    @Override
    protected boolean deliver(String recipient, String message) {
        // Safe 160-character truncation
        String payload = message;
        if (payload.length() > 160) {
            payload = payload.substring(0, 157) + "...";
        }
        System.out.printf("[SMS] -> %s%n  Text: %s (%d/160 chars)%n  Status: DELIVERED%n", 
            recipient, payload, payload.length());
        return true;
    }
}

// 4. Push Notification Sender
class PushSender extends BaseSender {
    @Override
    public String getChannelName() { return "PUSH"; }

    @Override
    protected boolean deliver(String recipient, String message) {
        if (recipient.length() < 10) {
            System.err.println("[PUSH] Delivery failed: Device token too short.");
            return false;
        }
        System.out.printf("[PUSH] -> Token: %s...%n  Payload: {"alert":"%s"}%n  Status: DELIVERED%n", 
            recipient.substring(0, 8), message);
        return true;
    }
}

// 5. Central Dispatcher
class NotificationDispatcher {
    private java.util.List<NotificationSender> senders = new java.util.ArrayList<>();

    public void registerChannel(NotificationSender sender) {
        if (sender != null) senders.add(sender);
    }

    public void broadcast(String alertMessage, java.util.Map<String, String> channelRecipients) {
        System.out.println("=======================================================");
        System.out.println("           SYSTEM ALERT BROADCAST DISPATCH             ");
        System.out.println("=======================================================");
        int sent = 0;
        for (NotificationSender sender : senders) {
            String recipient = channelRecipients.get(sender.getChannelName());
            if (recipient != null) {
                if (sender.send(recipient, alertMessage)) sent++;
                System.out.println();
            }
        }
        System.out.printf("Broadcast Complete: %d/%d channels delivered successfully.%n", sent, senders.size());
        System.out.println("=======================================================\n");
    }
}

